// SIN guard clauses: anidamiento profundo
function procesar(x?: number) {
    if (x != null) {
        if (x >= 0) { return `ok:${x}` }
    }
    return "inválido"
}

// CON guard clauses: flujo plano y legible
function procesar(x?: number) {
    if (x == null) return "faltante"
    if (x < 0)    return "inválido"
    return `ok:${x}`
}

