function* rango(inicio: number, fin: number) {
    for (let i = inicio; i < fin; i++) yield i
}

function* fibonacci() {
    let [a, b] = [0, 1]
    while (true) { yield a; [a, b] = [b, a + b] }
}

async function pipeline() {
